import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transform
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load and setup texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane with correct aspect ratio (512/320 = 1.6)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1);
  const planeMaterial = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text via fontAtlas
  const textMesh = ctx.fontAtlas(
    'Features 1',
    {
      fontSize: 0.34,
      fontFamily: 'Lora',
      fontWeight: 400,
      color: '#16161d',
    }
  );
  textMesh.position.z = 0.01;
  group.add(textMesh);

  // Cleanup handler
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    texture.dispose();
    if (textMesh && textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh && textMesh.material) textMesh.material.dispose();
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
